void ov81_022401C8(void *data, s32 arg1);

void ov81_022401C8(void *data, s32 arg1) {
    BattleFactoryApp *app = data;

    if (app->monSummaryAppMan != NULL) {
        return;
    }

    PokepicManager_HandleLoadImgAndOrPltt(app->monSpriteMan, arg1);

    if (app->plttData != NULL) {
        PaletteData_PushTransparentBuffers(app->plttData);
    }

    DoScheduledBgGpuUpdates(app->bgConfig);
    GF_RunVramTransferTasks();
    OamManager_ApplyAndResetBuffers();

    OS_SetIrqCheckFlag(OS_IE_V_BLANK);
}
